import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.distributed as dist


def _world_rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size(), dist.get_rank()
    return 1, 0


class _AllGatherLastDim(torch.autograd.Function):
    """Differentiable all_gather with concatenation along the last dim."""

    @staticmethod
    def forward(ctx, x):
        world, rank = _world_rank()
        ctx.world = world
        ctx.rank = rank
        if world == 1:
            return x
        x = x.contiguous()
        gathered = [torch.empty_like(x) for _ in range(world)]
        dist.all_gather(gathered, x)
        # keep local shard connected to the autograd graph
        gathered[rank] = x
        return torch.cat(gathered, dim=-1)

    @staticmethod
    def backward(ctx, grad_output):
        world = ctx.world
        rank = ctx.rank
        if world == 1:
            return grad_output
        chunks = grad_output.chunk(world, dim=-1)
        return chunks[rank].contiguous()


class _AllReduceSum(torch.autograd.Function):
    """Differentiable all_reduce (sum). Backward is identity."""

    @staticmethod
    def forward(ctx, x):
        world, _ = _world_rank()
        if world == 1:
            return x
        x = x.clone()
        dist.all_reduce(x, op=dist.ReduceOp.SUM)
        return x

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output


class ColumnParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        world, rank = _world_rank()
        assert out_features % world == 0, \
            "out_features must be divisible by world_size"
        self.out_features_per_partition = out_features // world

        # master_weight has shape [out_features, in_features] (nn.Linear layout).
        # Column parallel splits along the output dimension.
        start = rank * self.out_features_per_partition
        end = start + self.out_features_per_partition
        w_shard = master_weight[start:end, :].clone().detach()
        self.weight = nn.Parameter(w_shard)

        if bias:
            b = torch.zeros(self.out_features_per_partition,
                            dtype=self.weight.dtype,
                            device=self.weight.device)
            self.bias = nn.Parameter(b)
        else:
            self.register_parameter("bias", None)

    def forward(self, input_):
        local_out = F.linear(input_, self.weight, self.bias)
        return _AllGatherLastDim.apply(local_out)


class RowParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        world, rank = _world_rank()
        assert in_features % world == 0, \
            "in_features must be divisible by world_size"
        self.in_features_per_partition = in_features // world

        # master_weight has shape [out_features, in_features] (nn.Linear layout).
        # Row parallel splits along the input dimension.
        start = rank * self.in_features_per_partition
        end = start + self.in_features_per_partition
        w_shard = master_weight[:, start:end].clone().detach()
        self.weight = nn.Parameter(w_shard)

        if bias:
            b = torch.zeros(out_features,
                            dtype=self.weight.dtype,
                            device=self.weight.device)
            self.bias = nn.Parameter(b)
        else:
            self.register_parameter("bias", None)

    def forward(self, input_):
        # input_ is already scattered along the last dimension.
        local_out = F.linear(input_, self.weight)
        out = _AllReduceSum.apply(local_out)
        if self.bias is not None:
            out = out + self.bias
        return out
